package main

import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"strings"
)

type Shape interface {
	Name() string
	Corners() int
	DoubleArea() *big.Int
}

type shape struct {
	name    string
	corners int
	d       *big.Int
}

func (s shape) Name() string          { return s.name }
func (s shape) Corners() int          { return s.corners }
func (s shape) DoubleArea() *big.Int { return s.d }

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	var shapes []Shape
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) == 0 {
			continue
		}
		v := []*big.Int{}
		for _, x := range f[1:] {
			n, ok := new(big.Int).SetString(x, 10)
			if !ok {
				n = new(big.Int)
			}
			v = append(v, n)
		}
		for len(v) < 3 {
			v = append(v, new(big.Int))
		}
		d := new(big.Int)
		c := 4
		switch f[0] {
		case "square":
			d.Mul(v[0], v[0]).Mul(d, big.NewInt(2))
		case "rect":
			d.Mul(v[0], v[1]).Mul(d, big.NewInt(2))
		case "rtri":
			c = 3
			d.Mul(v[0], v[1])
		case "trap":
			d.Add(v[0], v[1]).Mul(d, v[2])
		default:
			continue
		}
		shapes = append(shapes, shape{f[0], c, d})
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	total := new(big.Int)
	var best Shape
	for _, s := range shapes {
		fmt.Fprintf(w, "%s corners=%d area2=%s\n", s.Name(), s.Corners(), s.DoubleArea())
		total.Add(total, s.DoubleArea())
		if best == nil || s.DoubleArea().Cmp(best.DoubleArea()) > 0 {
			best = s
		}
	}
	fmt.Fprintf(w, "total area2=%s\n", total)
	if best == nil {
		fmt.Fprintln(w, "largest=none")
	} else {
		fmt.Fprintf(w, "largest=%s area2=%s\n", best.Name(), best.DoubleArea())
	}
}

